// src/engine/worldgen/passes/pass00-grid.ts
function runGridPass(params) {
  const { cols, rows, seed } = params;
  const total = cols * rows;
  const elevation = new Float32Array(total);
  const temperature = new Float32Array(total);
  const moisture = new Float32Array(total);
  const isOcean = new Uint8Array(total).fill(1);
  const terrain = new Array(total).fill("ocean");
  const hasRiver = new Uint8Array(total);
  const lakeIds = new Int16Array(total).fill(-1);
  const drainageElevation = new Float32Array(total);
  const filledDepth = new Float32Array(total);
  const provinceIds = new Int16Array(total).fill(-1);
  const provinceRoles = new Uint8Array(total);
  const identityFn = (col, row) => {
    const c = Math.max(0, Math.min(cols - 1, Math.round(col)));
    const r = Math.max(0, Math.min(rows - 1, Math.round(row)));
    return elevation[r * cols + c];
  };
  return {
    cols,
    rows,
    seed,
    // WorldGenData fields
    elevation,
    temperature,
    moisture,
    isOcean,
    terrain,
    hasRiver,
    riverPaths: [],
    lakeIds,
    drainageElevation,
    filledDepth,
    // Province fields
    provinceIds,
    provinceRoles,
    provinces: [],
    provinceCapitalHexes: [],
    // Elevation features
    ridges: [],
    canyons: [],
    // Sampling stubs (elevation pass will replace sampleElevation)
    sampleElevation: identityFn,
    sampleTemperature: (col, row) => {
      const c = Math.max(0, Math.min(cols - 1, Math.round(col)));
      const r = Math.max(0, Math.min(rows - 1, Math.round(row)));
      return temperature[r * cols + c];
    },
    sampleMoisture: (col, row) => {
      const c = Math.max(0, Math.min(cols - 1, Math.round(col)));
      const r = Math.max(0, Math.min(rows - 1, Math.round(row)));
      return moisture[r * cols + c];
    }
  };
}

// src/lib/prng.ts
function mulberry32(seed) {
  return () => {
    let t = seed += 1831565813;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function fractalNoise(x, y, seed, octaves = 4, persistence = 0.5) {
  let total = 0;
  let amplitude = 1;
  let frequency = 1;
  let maxAmplitude = 0;
  for (let i = 0; i < octaves; i++) {
    const ix = Math.floor(x * frequency);
    const iy = Math.floor(y * frequency);
    const fx = x * frequency - ix;
    const fy = y * frequency - iy;
    const hash = (px, py) => {
      let h = px * 374761393 + py * 668265263 + (seed + i) * 1274126177 | 0;
      h = Math.imul(h ^ h >>> 13, h | 1);
      h = (h ^ h >>> 15) >>> 0;
      return h / 4294967296 * 2 - 1;
    };
    const n00 = hash(ix, iy);
    const n10 = hash(ix + 1, iy);
    const n01 = hash(ix, iy + 1);
    const n11 = hash(ix + 1, iy + 1);
    const sx = fx * fx * (3 - 2 * fx);
    const sy = fy * fy * (3 - 2 * fy);
    const nx0 = n00 + sx * (n10 - n00);
    const nx1 = n01 + sx * (n11 - n01);
    const value = nx0 + sy * (nx1 - nx0);
    total += value * amplitude;
    maxAmplitude += amplitude;
    amplitude *= persistence;
    frequency *= 2;
  }
  return total / maxAmplitude;
}

