  // Some defection (betray or be betrayed).
  doomed_innocent: {
    "tit-for-tat": 0.2,
    grudger: 0.1,
    pavlov: 0.15,
    "always-cooperate": 0.5,
    "always-defect": 0.05
  },
  // Story: Good person in a world that will break them. Tone: Tender, darkening.
