function getFoundationModifier(id) {
  return FOUNDATION_MODIFIERS.find((m) => m.id === id);
}
function getCreationSphereModifier(sphere) {
  return CREATION_SPHERE_MODIFIERS.find((m) => m.sphere === sphere);
}
function getBiomeModifier(terrain) {
  return BIOME_MODIFIERS.find((m) => m.terrain === terrain);
}
function getFormativeTraitSeed(id) {
  return FORMATIVE_TRAIT_SEEDS.find((s) => s.id === id);
}
function getBehavioralTraitSeed(id) {
  return BEHAVIORAL_TRAIT_SEEDS.find((s) => s.id === id);
}
function getBeatsForCultureTags(tags) {
  return INSIDER_BEATS.filter(
    (b) => b.requiredCultureTags.some((t) => tags.includes(t))
  );
}
