// src/engine/culturalTraits.ts
function instantiateFormativeTraits(graph, seedIds) {
  const nodeIds = [];
  for (const seedId of seedIds) {
    const seed = getFormativeTraitSeed(seedId);
    if (!seed) continue;
    const nodeId = `trait_formative_${seedId}`;
    if (graph.getNode(nodeId)) {
      nodeIds.push(nodeId);
      continue;
    }
    const traitDef = {
      subcategory: "innate",
      description: seed.description,
      importance: 0.7,
      // Formative traits are important
      maxLevel: 1,
      // Binary — either you have it or not
      visibility: "public",
      domainContributions: seed.domainContributions,
      tags: seed.tags,
      flavorText: seed.name,
      culturalOrigin: true
    };
    graph.addNode({
      id: nodeId,
      type: "trait",
      name: seed.name,
      properties: traitDef
    });
    nodeIds.push(nodeId);
  }
  return nodeIds;
}
function instantiateBehavioralTraits(graph, seedIds) {
  const nodeIds = [];
  for (const seedId of seedIds) {
    const seed = getBehavioralTraitSeed(seedId);
    if (!seed) continue;
    const nodeId = `trait_behavioral_${seedId}`;
    if (graph.getNode(nodeId)) {
      nodeIds.push(nodeId);
      continue;
    }
    const traitDef = {
      subcategory: "cultural",
      description: seed.description,
      importance: 0.6,
      // Behavioral traits are moderately important
      maxLevel: 1,
      // Binary assignment
      visibility: "public",
      domainContributions: seed.domainContributions,
      strengthThresholds: seed.strengthThresholds,
      tags: seed.tags,
      flavorText: seed.name
    };
    graph.addNode({
      id: nodeId,
      type: "trait",
      name: seed.name,
      properties: traitDef
    });
    nodeIds.push(nodeId);
  }
  return nodeIds;
}
function grantFormativeTraits(graph, actorId, traitNodeIds, tick) {
  for (const traitId of traitNodeIds) {
    const edgeId = `e.has_trait.${actorId}.${traitId}`;
    if (graph.getEdge(edgeId)) continue;
    graph.addEdge({
      id: edgeId,
      source: actorId,
      target: traitId,
      type: "has_trait",
      properties: {
        level: 1,
        acquiredTick: tick,
        lastReinforcedTick: tick,
        source: "cultural_formative",
        visibility: "public"
      }
    });
  }
}
function grantBehavioralTraits(graph, actorId, traitNodeIds, tick) {
  for (const traitId of traitNodeIds) {
    const edgeId = `e.has_trait.${actorId}.${traitId}`;
    if (graph.getEdge(edgeId)) continue;
    graph.addEdge({
      id: edgeId,
      source: actorId,
      target: traitId,
      type: "has_trait",
      properties: {
        level: 1,
        acquiredTick: tick,
        lastReinforcedTick: tick,
        source: "cultural_behavioral",
        visibility: "public"
      }
    });
  }
}
function getActorCulturalStrength(graph, actorId) {
  const edges = graph.getOutgoingEdges(actorId, "belongs_to");
  let maxStrength = 0;
  for (const edge of edges) {
    const props = edge.properties;
    if (props.culturalStrength > maxStrength) {
      maxStrength = props.culturalStrength;
    }
  }
  return maxStrength;
}

