var CLAIMED_NAME_PATTERNS = [
  "The {culture_adj} {geo_noun}",
  "{culture_noun}{geo_suffix}",
  "The {culture_adj} {feature_type}",
  "{culture_noun} {geo_noun}"
];
var UNCLAIMED_NAME_PATTERNS = [
  "The {geo_adj} {feature_type}",
  "The {geo_noun}"
];

// src/engine/regionNaming.ts
function pick3(rng, arr) {
  return arr[Math.floor(rng() * arr.length)];
}
var FEATURE_LABELS2 = {
  mountain_range: "Mountains",
  hill_country: "Hills",
  forest: "Forest",
  plains: "Plains",
  desert: "Desert",
  wetland: "Marshes",
  tundra: "Wastes",
  river: "River",
  lake: "Lake",
  sea: "Sea"
};
function generateRegionName(featureType, historicalCultureId, graph, rng, usedNames) {
  const maxRetries = 3;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const name = historicalCultureId ? generateClaimedName(featureType, historicalCultureId, graph, rng) : generateWildernessName(featureType, rng);
    if (!usedNames.has(name) || attempt === maxRetries) {
      return name;
    }
  }
  return generateWildernessName(featureType, rng);
}
function generateClaimedName(featureType, cultureId, graph, rng) {
  const cultureNode = graph.getNode(cultureId);
  const identity = cultureNode?.properties.cultureIdentity;
  const foundFrags = identity ? CULTURE_NAME_FRAGMENTS.foundation[identity.foundationBias] ?? [] : [];
  const sphereFrags = identity?.veneratedSpheres[0] ? CULTURE_NAME_FRAGMENTS.sphere[identity.veneratedSpheres[0]] ?? [] : [];
  const cultureAdjs = [...foundFrags];
  const cultureNouns = [...sphereFrags];
  if (cultureAdjs.length === 0) cultureAdjs.push("Ancient", "Forgotten", "Lost");
  if (cultureNouns.length === 0) cultureNouns.push("Ruin", "Echo", "Shadow");
  const geoKey = featureType === "sea" ? "lake" : featureType;
  const geo = REGION_NAME_FRAGMENTS[geoKey];
  const pattern = pick3(rng, CLAIMED_NAME_PATTERNS);
  return pattern.replace("{culture_adj}", pick3(rng, cultureAdjs)).replace("{culture_noun}", pick3(rng, cultureNouns)).replace("{geo_noun}", pick3(rng, geo.nouns)).replace("{geo_suffix}", pick3(rng, geo.suffixes)).replace("{feature_type}", FEATURE_LABELS2[featureType]);
}
function generateWildernessName(featureType, rng) {
  const geoKey = featureType === "sea" ? "lake" : featureType;
  const geo = REGION_NAME_FRAGMENTS[geoKey];
  const pattern = pick3(rng, UNCLAIMED_NAME_PATTERNS);
  return pattern.replace("{geo_adj}", pick3(rng, geo.adjectives)).replace("{geo_noun}", pick3(rng, geo.nouns)).replace("{feature_type}", FEATURE_LABELS2[featureType]);
}

