      category: "modifier_resolution",
      agentId: nodeId,
      summary: `${attribute}: ${baseValue} ${totalDelta >= 0 ? "+" : ""}${totalDelta} = ${finalValue}`,
      nodeId,
      attribute,
      baseValue,
      modifiers,
      finalValue
