// src/data/game-config.ts
var MANDATE_PRIMARY_WEIGHT = 3;
var MANDATE_SECONDARY_WEIGHT = 2;
var MANDATE_BASE_WEIGHT = 1;
var MANDATE_ACHIEVABLE_MULTIPLIER = 2;

// src/engine/mandateGenerator.ts
function mulberry3211(seed) {
  let s = seed | 0;
  return () => {
    s = s + 1831565813 | 0;
    let t = Math.imul(s ^ s >>> 15, 1 | s);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function scoreTemplate(template, alignment) {
  const { primary, secondary } = alignment;
  const { sphereAffinities, type } = template;
  let baseWeight;
  if (sphereAffinities.includes(primary)) {
    baseWeight = MANDATE_PRIMARY_WEIGHT;
  } else if (sphereAffinities.includes(secondary)) {
    baseWeight = MANDATE_SECONDARY_WEIGHT;
  } else {
    baseWeight = MANDATE_BASE_WEIGHT;
  }
  if (type === "simulation_achievable") {
    return baseWeight * MANDATE_ACHIEVABLE_MULTIPLIER;
  }
  return baseWeight;
}
function generateMandate(cosmology, alignment, seed) {
  const scores = MANDATE_TEMPLATES.map(
    (template) => scoreTemplate(template, alignment)
  );
  const cumulativeWeights = [];
  let totalWeight = 0;
  for (let i = 0; i < scores.length; i++) {
    totalWeight += scores[i];
    cumulativeWeights.push(totalWeight);
  }
  const rng = mulberry3211(seed);
  const randomValue = rng() * totalWeight;
  for (let i = 0; i < cumulativeWeights.length; i++) {
    if (randomValue < cumulativeWeights[i]) {
      return MANDATE_TEMPLATES[i];
    }
  }
  return MANDATE_TEMPLATES[0];
}

// src/engine/mandate.ts
var STAGE_ORDER = ["setup", "escalation", "culmination"];
function createMandateState(mandateId, tick) {
  return {
    mandateId,
    currentStage: "setup",
    progress: 0,
    completed: false,
    failed: false,
    assignedTick: tick,
    stageCompletedTicks: {}
  };
}
function evaluateCondition(graph, condition, ascendantId) {
  switch (condition.type) {
    case "node_count": {
      const { edgeType, edgeTarget, minTier, minCount } = condition.params;
      const targetNode = graph.getNode(edgeTarget);
      if (!targetNode) return false;
      const connectedEdges = [
        ...graph.getIncomingEdges(edgeTarget),
        ...graph.getOutgoingEdges(edgeTarget)
      ].filter((e) => e.type === edgeType);
      const qualifying = minTier != null ? connectedEdges.filter((e) => e.properties.tier >= minTier) : connectedEdges;
      return qualifying.length >= minCount;
    }
    case "edge_count": {
      const { edgeType, minCount } = condition.params;
      const allEdges = graph.getAllEdges().filter((e) => e.type === edgeType);
      return allEdges.length >= minCount;
    }
    case "actor_tier": {
      const { minTier, minCount } = condition.params;
      const threadEdges = graph.getOutgoingEdges(ascendantId).filter((e) => e.type === "thread" && e.properties.tier >= minTier);
      return threadEdges.length >= minCount;
    }
    case "sphere_weight": {
      const { sphere, minWeight, minRegions } = condition.params;
      const locations = graph.getNodesByType("location");
      let qualifyingRegions = 0;
      for (const loc of locations) {
        const sphereEdges = graph.getOutgoingEdges(loc.id, "sphere_influence");
        const match = sphereEdges.find((e) => {
          const targetNode = graph.getNode(e.target);
          return targetNode && targetNode.name.toLowerCase() === sphere;
        });
        if (match && match.properties.weight >= minWeight) {
          qualifyingRegions++;
        }
      }
      return qualifyingRegions >= minRegions;
    }
    case "custom":
      return false;
    default:
      return false;
  }
}
function evaluateMandate(graph, mandate, state2, ascendantId, _tick) {
  if (state2.completed || state2.failed) return state2;
  const stageIndex = STAGE_ORDER.indexOf(state2.currentStage);
  const stageDef = mandate.stages[stageIndex];
  if (!stageDef || stageDef.conditions.length === 0) {
    return { ...state2, progress: 1 };
  }
  const results = stageDef.conditions.map((c) => evaluateCondition(graph, c, ascendantId));
  const metCount = results.filter(Boolean).length;
  const progress = metCount / stageDef.conditions.length;
  return { ...state2, progress };
}
function advanceMandateStage(state2, tick) {
  const stageIndex = STAGE_ORDER.indexOf(state2.currentStage);
  const completedTicks = { ...state2.stageCompletedTicks, [state2.currentStage]: tick };
  if (stageIndex >= STAGE_ORDER.length - 1) {
    return {
      ...state2,
      completed: true,
      stageCompletedTicks: completedTicks
    };
  }
  return {
    ...state2,
    currentStage: STAGE_ORDER[stageIndex + 1],
    progress: 0,
    stageCompletedTicks: completedTicks
  };
}

