var MAX_SPHERE_SCORE = 10;
var ACTION_PRESSURE_SUCCESS = 3;
var ACTION_PRESSURE_FAILURE = 1;
var CONTROL_PRESSURE_PER_TICK = 1;
var ENCOUNTER_PRESSURE_PER_STEP = 1;
var DOOM_PRESSURE_PER_TIER = 4;
var RIVAL_PRESSURE_MAGNITUDE = 2;
var MANDATE_PRESSURE_MILESTONE = 2;
var MANDATE_PRESSURE_COMPLETION = 5;
var AGENT_PRESENCE_RATIO = 1;
var ARCHETYPE_SPHERE_BONUS_PRIMARY = 2;
var ARCHETYPE_SPHERE_BONUS_SECONDARY = 1;
function triangleCost(n) {
  return n;
}
function createDefaultSphereAffinity() {
  const scores = {};
  const progress = {};
  for (const sphere of SPHERE_NAMES) {
    scores[sphere] = 0;
    progress[sphere] = 0;
  }
  return { scores, progress };
}
var TERRAIN_SPHERE_TABLE = {
  // Forest
  forest: { life: 3, spirit: 1 },
  // Mountains
  mountains: { matter: 3, force: 1 },
  // Plains / grassland
  plains: { energy: 2, life: 1 },
  // Desert
  desert: { force: 2, entropy: 1 },
  // Swamp / wet
  swamp: { entropy: 2, life: 1 },
  // Coast / ocean
  coast: { time: 2, energy: 1 },
  // Volcanic
  volcanic: { force: 3, entropy: 2 },
  // Tundra / ice
  tundra: { entropy: 2, time: 1 },
  // Sacred / enchanted
  sacred_grove: { spirit: 3, life: 2 },
  // Ruins / broken lands
  ruins: { time: 2, mind: 1 }
};
var LOCATION_SPHERE_TABLE = {
  // Settlements — life (communities of living people)
  hamlet: { life: 1 },
  town: { mind: 1 },
  city: { mind: 1 },
  capital: { force: 1 },
  // Rural/resource
  camp: { energy: 1 },
  farmland: { life: 1 },
  // Military
  castle: { force: 1 },
  fort: { force: 1 },
  tower: { mind: 1 },
  // Religious
  shrine: { spirit: 1 },
  temple: { spirit: 1 },
  // Industrial
  mining: { matter: 1 },
  // Decay
  ruins: { time: 1 },
  ruined_tower: { time: 1 },
  ruined_city: { entropy: 1 },
  ruined_village: { entropy: 1 },
  // Conflict
  battleground: { entropy: 1 },
  // Refuge
  oasis: { energy: 1 },
  // Mystery
  unexplored_poi: { spirit: 1 }
};
function getTerrainSphereScores(terrain) {
  if (terrain in TERRAIN_SPHERE_TABLE) {
    return TERRAIN_SPHERE_TABLE[terrain];
  }
  if (terrain === "temperate_forest" || terrain === "dense_forest" || terrain === "boreal_forest" || terrain === "jungle" || terrain === "tropical_forest" || terrain === "evergreen_forest" || terrain === "light_forest" || terrain === "great_home_trees" || terrain === "forested_hills") {
    return TERRAIN_SPHERE_TABLE["forest"];
  }
  if (terrain === "dead_forest" || terrain === "broken_lands") {
    return TERRAIN_SPHERE_TABLE["ruins"];
  }
  if (terrain === "high_mountains" || terrain === "mountain_pass" || terrain === "hills" || terrain === "plateau" || terrain === "badlands") {
    return TERRAIN_SPHERE_TABLE["mountains"];
  }
  if (terrain === "grassland" || terrain === "farmland" || terrain === "savanna" || terrain === "steppe" || terrain === "floodplain") {
    return TERRAIN_SPHERE_TABLE["plains"];
  }
  if (terrain === "rocky_desert" || terrain === "sand_dunes") {
    return TERRAIN_SPHERE_TABLE["desert"];
  }
  if (terrain === "oasis") {
    return { force: 1, life: 2, entropy: 1 };
  }
  if (terrain === "marsh" || terrain === "moor_bog") {
    return TERRAIN_SPHERE_TABLE["swamp"];
  }
  if (terrain === "ocean" || terrain === "deep_ocean" || terrain === "tropical_ocean" || terrain === "coastal_shallows" || terrain === "lake" || terrain === "river" || terrain === "reef") {
    return TERRAIN_SPHERE_TABLE["coast"];
  }
  if (terrain === "volcano") {
    return TERRAIN_SPHERE_TABLE["volcanic"];
  }
  if (terrain === "glacier" || terrain === "arctic" || terrain === "snow_fields") {
    return TERRAIN_SPHERE_TABLE["tundra"];
  }
  return {};
}

// src/engine/sphereAffinity.ts
function getNodeSphereAffinity(node) {
  return node.properties.sphereAffinity;
}
function seedHexSphereAffinity(terrainType) {
  const base = createDefaultSphereAffinity();
  const terrainScores = getTerrainSphereScores(terrainType);
  for (const [sphere, score] of Object.entries(terrainScores)) {
    base.scores[sphere] = score;
  }
  return base;
}
function seedAgentSphereAffinity(sphereAlignment2) {
  const base = createDefaultSphereAffinity();
  if (!sphereAlignment2) return base;
  const sorted = Object.entries(sphereAlignment2).filter(([, weight]) => weight > 0).sort((a, b) => b[1] - a[1]);
  if (sorted.length > 0) {
    const primarySphere = sorted[0][0];
    base.scores[primarySphere] = Math.min(ARCHETYPE_SPHERE_BONUS_PRIMARY, MAX_SPHERE_SCORE);
  }
  if (sorted.length > 1) {
    const secondarySphere = sorted[1][0];
    base.scores[secondarySphere] = Math.min(ARCHETYPE_SPHERE_BONUS_SECONDARY, MAX_SPHERE_SCORE);
  }
  return base;
}
function seedLocationSphereAffinity(hexAffinity, locationSubtype) {
  const base = createDefaultSphereAffinity();
  for (const sphere of SPHERE_NAMES) {
    base.scores[sphere] = hexAffinity.scores[sphere];
  }
  if (locationSubtype) {
    const typeScores = LOCATION_SPHERE_TABLE[locationSubtype];
    if (typeScores) {
      for (const [sphere, score] of Object.entries(typeScores)) {
        base.scores[sphere] = Math.min(
          base.scores[sphere] + score,
          MAX_SPHERE_SCORE
        );
      }
    }
  }
  return base;
}
var SPHERE_DECISION_WEIGHT = 0.15;
var SPHERE_AXIOLOGICAL_MAP = {
  force: { pair: "courage_prudence", direction: 1 },
  // Bold, assertive
  matter: { pair: "loyalty_ambition", direction: 1 },
  // Order over freedom
  energy: { pair: "loyalty_ambition", direction: -1 },
  // Freedom over order
  life: { pair: "mercy_ruthlessness", direction: 1 },
  // Compassion, preservation
  mind: { pair: "honesty_cunning", direction: 1 },
  // Knowledge, transparency
  spirit: { pair: "honesty_cunning", direction: -1 },
  // Intuition, hidden truth
  time: { pair: "courage_prudence", direction: -1 },
  // Patient, measured
  entropy: { pair: "mercy_ruthlessness", direction: -1 }
  // Ruthlessness, consumption
};
function getDominantSphere(affinity) {
  let maxScore = 0;
  let dominant = null;
  for (const sphere of SPHERE_NAMES) {
    if (affinity.scores[sphere] > maxScore) {
      maxScore = affinity.scores[sphere];
      dominant = sphere;
    }
  }
  return dominant;
}
function applyAxiologicalShift(profile, mapping) {
  const current = profile[mapping.pair] ?? 0;
  const shifted = Math.max(-1, Math.min(1, current + mapping.direction * SPHERE_DECISION_WEIGHT));
  return { ...profile, [mapping.pair]: shifted };
}

