// src/engine/questVisibility.ts
function isEncounterVisibleToAgent(graph, agentId, visibleTo) {
  if (!visibleTo || visibleTo.length === 0) return true;
  if (visibleTo.includes("all")) return true;
  const agentNode = graph.getNode(agentId);
  if (!agentNode) return false;
  const positiveFilters = [];
  const negativeFilters = [];
  for (const filter of visibleTo) {
    if (filter.startsWith("not_")) {
      negativeFilters.push(filter);
    } else {
      positiveFilters.push(filter);
    }
  }
  for (const filter of negativeFilters) {
    const rest = filter.slice(4);
    const [prefix, targetId] = rest.split(":");
    switch (prefix) {
      case "faction": {
        const memberEdges = graph.getOutgoingEdges(agentId, "member_of");
        const isMember = memberEdges.some((e) => {
          const props = e.properties;
          return props.factionDefId === targetId;
        });
        if (isMember) return false;
        break;
      }
      default:
        break;
    }
  }
  if (positiveFilters.length === 0) return true;
  for (const filter of positiveFilters) {
    const [prefix, targetId] = filter.split(":");
    switch (prefix) {
      case "agent":
        if (agentId === targetId) return true;
        break;
      case "faction": {
        const factionEdges = graph.getOutgoingEdges(agentId, "member_of");
        if (factionEdges.some((e) => e.target === targetId)) return true;
        break;
      }
      case "archetype": {
        const archetype = agentNode.properties?.narrativeArchetype;
        if (archetype === targetId) return true;
        break;
      }
      case "culture": {
        const cultureEdges = graph.getOutgoingEdges(agentId, "belongs_to");
        if (cultureEdges.some((e) => e.target === targetId)) return true;
        break;
      }
      default:
        break;
    }
  }
  return false;
}

// src/data/threat-content.ts
var THREAT_FACTION_WEIGHT = 0.4;
var THREAT_HOSTILE_AGENT_WEIGHT = 0.3;
var THREAT_ENCOUNTER_WEIGHT = 0.2;

// src/engine/threatRating.ts
function computeHexThreatRating(graph, locationId) {
  let factionThreat = 0;
  let hostileAgentThreat = 0;
  let encounterThreat = 0;
  const controlEdges = graph.getIncomingEdges(locationId, "controls");
  for (const edge of controlEdges) {
    const controller = graph.getNode(edge.source);
    if (controller) {
      const hostility = controller.properties?.hostilityToPlayer ?? 0;
      factionThreat = Math.max(factionThreat, hostility);
    }
  }
  const locatedAtEdges = graph.getIncomingEdges(locationId, "located_at");
  let hostileCount = 0;
  let totalAgents = 0;
  for (const edge of locatedAtEdges) {
    const agent = graph.getNode(edge.source);
    if (agent && agent.properties?.actorType === "individual") {
      totalAgents++;
      const strategy = agent.properties?.cooperationStrategy;
      if (strategy === "always_defect" || strategy === "grudger") {
        hostileCount++;
      }
      const memberEdges = graph.getOutgoingEdges(edge.source, "member_of");
      for (const mEdge of memberEdges) {
        const faction = graph.getNode(mEdge.target);
        if (faction && (faction.properties?.hostilityToPlayer ?? 0) > 0.5) {
          hostileCount++;
          break;
        }
      }
    }
  }
  hostileAgentThreat = totalAgents > 0 ? Math.min(1, hostileCount / Math.max(1, totalAgents)) : 0;
  const encounterEdges = graph.getIncomingEdges(locationId, "encounter_at");
  if (encounterEdges.length > 0) {
    let totalThreat = 0;
    for (const edge of encounterEdges) {
      const enc = graph.getNode(edge.source);
      if (enc) {
        const rating = enc.properties?.threatRating;
        totalThreat += threatRatingToNumber(rating);
      }
    }
    encounterThreat = totalThreat / encounterEdges.length;
  }
  const raw = factionThreat * THREAT_FACTION_WEIGHT + hostileAgentThreat * THREAT_HOSTILE_AGENT_WEIGHT + encounterThreat * THREAT_ENCOUNTER_WEIGHT;
  return Math.max(0, Math.min(1, raw));
}
function threatRatingToNumber(rating) {
  switch (rating) {
    case "trivial":
      return 0.1;
    case "easy":
    case "minor":
      return 0.25;
    case "moderate":
      return 0.5;
    case "hard":
    case "serious":
      return 0.75;
    case "deadly":
      return 1;
    default:
      return 0.3;
  }
}

// src/engine/movementCandidates.ts
function scoreMovementCandidate(motivationPull, tickDistance) {
  const distanceDecay = 1 / (1 + DISTANCE_DECAY_FACTOR * tickDistance);
  return motivationPull * distanceDecay;
}
function computeThreatModifier(threatRating, couragePrudence) {
  const courageFactor = (couragePrudence + 1) / 2;
  const modifier = 1 - threatRating * (1 - courageFactor);
  return Math.max(THREAT_MODIFIER_FLOOR, modifier);
}
function generateMovementCandidates(graph, agentId, currentLocationId, profile) {
  const candidates = [];
  const allLocations = graph.getNodesByType("location");
  for (const loc of allLocations) {
    if (loc.id === currentLocationId) continue;
    const pathResult = findShortestPath(graph, agentId, currentLocationId, loc.id);
    if (!pathResult || pathResult.totalCost > MAX_CANDIDATE_DISTANCE) continue;
    if (pathResult.path.length === 0) continue;
    const { pull: basePull, bestTemplateId } = computeBasePull(graph, loc.id, agentId, profile);
    if (basePull <= 0) continue;
    const threat = computeHexThreatRating(graph, loc.id);
    const threatMod = computeThreatModifier(threat, profile.courage_prudence);
    const score = scoreMovementCandidate(basePull * threatMod, pathResult.totalCost);
    candidates.push({
      destinationId: loc.id,
      bestTemplateId,
      motivationPull: basePull,
      distanceDecay: 1 / (1 + DISTANCE_DECAY_FACTOR * pathResult.totalCost),
      score,
      tickDistance: pathResult.totalCost,
      path: pathResult.path
    });
  }
  candidates.sort((a, b) => b.score - a.score);
  return candidates;
}
function computeBasePull(graph, locationId, agentId, profile) {
  const node = graph.getNode(locationId);
  if (!node) return { pull: 0, bestTemplateId: "" };
  const locType = node.properties?.locationType;
  if (!locType || locType === "sublocation") return { pull: 0, bestTemplateId: "" };
  const ambitionBonus = Math.max(0, profile.loyalty_ambition) * P0_AMBITION_WEIGHT;
  const baseHeuristicPull = P0_BASE_MOTIVATION_PULL + ambitionBonus;
  const encounterEdges = graph.getIncomingEdges(locationId, "encounter_at");
  let bestPull = 0;
  let bestTemplateId = "";
  for (const edge of encounterEdges) {
    const encNode = graph.getNode(edge.source);
    if (!encNode) continue;
    const visibleTo = encNode.properties?.visibleTo;
    if (!isEncounterVisibleToAgent(graph, agentId, visibleTo)) continue;
    const questPriority = encNode.properties?.questPriority ?? DEFAULT_QUEST_PRIORITY;
    const pull = baseHeuristicPull * questPriority;
    if (pull > bestPull) {
      bestPull = pull;
      bestTemplateId = encNode.id;
    }
  }
  if (bestPull === 0) {
    return { pull: baseHeuristicPull, bestTemplateId: "" };
  }
  return { pull: bestPull, bestTemplateId };
}

