function handleCommand(line) {
  const trimmed = line.trim();
  if (!trimmed) return true;
  const [cmd, ...rest] = trimmed.split(/\s+/);
  const arg = rest.join(" ");
  switch (cmd.toLowerCase()) {
    case "tick":
    case "t": {
      const n = parseInt(arg, 10);
      doTick(isNaN(n) || n < 1 ? 1 : n);
      break;
    }
    case "run":
    case "start": {
      const n = parseFloat(arg);
      startAutoRun(isNaN(n) ? void 0 : n);
      break;
    }
    case "pause":
    case "stop":
      stopAutoRun();
      break;
    case "speed": {
      const n = parseFloat(arg);
      if (isNaN(n) || n <= 0) {
        console.log(`Current speed: ${autoRunSpeed} ticks/sec`);
      } else {
        autoRunSpeed = n;
        console.log(`Speed set to ${autoRunSpeed} ticks/sec`);
        if (autoRunTimer) startAutoRun();
      }
      break;
    }
    case "status":
    case "s":
      printStatus();
      break;
    case "agents":
      printAgents();
      break;
    case "agent": {
      if (!arg) {
        console.log(`${RED}Usage: agent <id or name>${RESET}`);
      } else {
        printAgent(arg);
      }
      break;
    }
    case "events":
    case "e": {
      const n = parseInt(arg, 10);
      printEvents(isNaN(n) ? 10 : n);
      break;
    }
    case "graph":
    case "g":
      printGraph();
      break;
    case "locations":
    case "locs":
      printLocations();
      break;
    case "doom":
      printDoom();
      break;
    case "mandate":
      printMandate();
      break;
    case "essence":
      printEssence();
      break;
    case "encounters":
    case "actions":
      printEncounters();
      break;
    case "factions":
      printFactions();
      break;
    case "traces":
    case "tr": {
      const n = parseInt(arg, 10);
      printTraces(isNaN(n) ? 10 : n);
      break;
    }
    case "seed":
      console.log(`Seed: ${state.seed}`);
      break;
    case "eval": {
      if (!arg) {
        console.log(`${RED}Usage: eval <expression>${RESET}`);
      } else {
        try {
          const fn = new Function("state", `return (${arg})`);
          const result = fn(state);
          console.log(result);
        } catch (err) {
          console.log(`${RED}${err instanceof Error ? err.message : String(err)}${RESET}`);
        }
      }
      break;
    }
    case "help":
    case "h":
    case "?":
      printHelp();
      break;
    case "quit":
    case "exit":
    case "q":
      return false;
    default:
      console.log(`${RED}Unknown command: ${cmd}${RESET}. Type 'help' for commands.`);
  }
  return true;
}
